self.KB_CONTENT["card:752189"]={"id":"card:752189","ty":"card","sourceId":"752189","title":"『分錄性質設定-領料單』中的『單別名稱』為何？","ver":"iGP","topic":"領料單","keywords":["領料單","單別","分錄","別名"],"y":"other","answer":"* 依照單別資料自動顯示單別名稱，僅作顯示不可修改。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
