self.KB_CONTENT["card:780223"]={"id":"card:780223","ty":"card","sourceId":"780223","title":"『S/I資料建立作業』的作業重點有哪些？","ver":"GP4以上","topic":"採購單","keywords":["採購單","廠商","狀態","權限"],"y":"explain","answer":"作業重點1.『：資料查詢』(icon)，串建檔查詢介面* 建檔時，工具列各按鈕狀態應依據使用者權限設定。(1).供應商查詢:呼叫『供應廠商資料建立作業』(PURI01)(2).採購單查詢:呼叫『採購單建立作業』(PURI07)六、報關贖單作業程序","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
