self.KB_CONTENT["field:829951"]={"id":"field:829951","ty":"field","sourceId":"829951","title":"客戶代號","ver":"GP4 以上","topic":"","keywords":[],"job":"收款單建立作業","code":"","answer":"『收款單建立作業-ACRI03』操作時無法將多個【客戶代號】的資料在同一單據一起收款，一張「收款單」只可以輸入一個【客戶代號】","file":"fields.jsonl"};
